576: function buildMinimap(track, round) {
577:   const canvas = $('minimap');
578:   const w = canvas.width, h = canvas.height;
579:   let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
580:   track.samples.forEach(s => {
581:     minX = Math.min(minX, s.p.x); maxX = Math.max(maxX, s.p.x);
582:     minZ = Math.min(minZ, s.p.z); maxZ = Math.max(maxZ, s.p.z);
583:   });
584:   const pad = 34;
585:   const span = Math.max(maxX - minX, maxZ - minZ);
586:   const scale = (Math.min(w, h) - pad * 2) / span;
587:   const ox = w / 2 - ((minX + maxX) / 2) * scale;
588:   const oz = h / 2 - ((minZ + maxZ) / 2) * scale;
589:   const tx = (x) => ox + x * scale;
590:   const tz = (z) => oz + z * scale;
591: 
592:   const off = document.createElement('canvas');
593:   off.width = w; off.height = h;
594:   const ctx = off.getContext('2d');
595:   ctx.clearRect(0, 0, w, h);
596:   ctx.lineJoin = 'round';
597:   ctx.lineCap = 'round';
598:   ctx.beginPath();
599:   track.samples.forEach((s, i) => {
600:     const x = tx(s.p.x), z = tz(s.p.z);
601:     if (i === 0) ctx.moveTo(x, z); else ctx.lineTo(x, z);
602:   });
603:   ctx.closePath();
604:   ctx.strokeStyle = 'rgba(6, 10, 18, 0.9)';
605:   ctx.lineWidth = 19;
606:   ctx.stroke();
607:   ctx.strokeStyle = 'rgba(190, 215, 240, 0.42)';
608:   ctx.lineWidth = 10;
609:   ctx.stroke();
610:   ctx.strokeStyle = 'rgba(255, 255, 255, 0.28)';
611:   ctx.lineWidth = 2;
612:   ctx.stroke();
613: 
614:   // start line
615:   const s0 = track.samples[0];
616:   const sx = tx(s0.p.x), sz = tz(s0.p.z);
617:   ctx.fillStyle = '#ff6417';
618:   ctx.beginPath();
619:   ctx.arc(sx, sz, 5.5, 0, Math.PI * 2);
620:   ctx.fill();
621: 
622:   const minimap = { off, tx, tz, w, h, track, canvas, ctx: canvas.getContext('2d') };
623:   minimap.ctx.clearRect(0, 0, w, h);
624:   minimap.ctx.drawImage(off, 0, 0);
625:   drawMinimap(minimap, []);
626:   return minimap;
627: }
