1341: function updateRace(dt) {
1342:   const game = state.game;
1343:   if (!game || game.paused) return;
1344:   game.time += dt;
1345: 
1346:   if (game.phase === 'countdown') {
1347:     game.countdown -= dt;
1348:     countdownDisplay(game);
1349:     updateStartLights(game);
1350:     state.audio.setEngine(8, 0.2, false);
1351:     // idle engine blips
1352:     if (game.countdown <= 1.02) {
1353:       game.phase = 'racing';
1354:       game.lightsOn = 0;
1355:       game.countdown = 1;
1356:       game.player.crossings = 0;
1357:       game.racers.forEach((r) => { r.crossings = 0; r.lastIdx = game.track.nearest(r.pos).idx; });
1358:       const el = $('countdown');
1359:       el.textContent = 'GO!';
1360:       el.className = 'countdown go';
1361:       state.audio.countdown(0);
1362:       setTimeout(() => { if (state.game === game && game.phase === 'racing') { el.className = 'countdown'; el.textContent = ''; } }, 1050);
1363:       game.phase = 'racing';
1364:       game.raceTime = 0;
1365:     }
1366:     updateStartLights(game);
1367:     updateCamera(game, dt);
1368:     updateHUD(game, dt, true);
1369:     return;
1370:   }
1371: 
1372:   if (game.phase === 'racing' || game.phase === 'finishing') {
1373:     game.raceTime += dt;
1374:   }
1375: 
1376:   // player
1377:   if (game.phase === 'racing' && !game.player.finished) {
1378:     updatePlayer(game, dt);
1379:   } else if (game.player.finished) {
1380:     // coast to a stop
1381:     game.player.vel.multiplyScalar(Math.exp(-1.6 * dt));
1382:     game.player.speed *= Math.exp(-1.6 * dt);
1383:     game.player.pos.x += game.player.vel.x * dt;
1384:     game.player.pos.z += game.player.vel.y * dt;
1385:   }
1386: 
1387:   // AI
1388:   game.racers.forEach((r) => {
1389:     if (r.isPlayer) return;
1390:     updateAI(game, r, dt);
1391:   });
1392: 
1393:   // collisions
1394:   updateCollisions(game);
1395: 
1396:   // state/progress
1397:   game.racers.forEach((r) => updateRacerState(game, r, dt));
1398: 
1399:   // particles & camera
1400:   updateParticles(game, dt);
1401:   updateCamera(game, dt);
1402:   updateStartLights(game);
1403:   updateHUD(game, dt);
1404: 
1405:   // engine sound
1406:   state.audio.setEngine(game.player.speed, controls().throttle ? 1 : 0, game.player.boost);
1407: 
1408:   // results
1409:   if (game.resultsTimer > 0) {
1410:     game.resultsTimer -= dt;
1411:     if (game.resultsTimer <= 0 && !game.resultsShown) {
1412:       game.resultsShown = true;
1413:       game.phase = 'done';
1414:       showResults();
1415:     }
1416:   }
1417: }
