1573: let lastT = 0;
1574: function loop(t) {
1575:   requestAnimationFrame(loop);
1576:   const now = t / 1000;
1577:   let dt = Math.min(0.05, now - lastT || 0.016);
1578:   lastT = now;
1579:   if (!state.renderer) return;
1580: 
1581:   if (state.screen === 'menu' || state.screen === 'loading') {
1582:     animateShowroom(dt, now);
1583:     state.renderer.render(state.menuScene || new THREE.Scene(), state.menuCamera);
1584:     return;
1585:   }
1586: 
1587:   if (state.screen === 'pause' || state.screen === 'results' || state.screen === 'champion') {
1588:     if (state.game && state.screen === 'pause') {
1589:       // frozen frame
1590:       state.renderer.render(state.game.scene, state.camera);
1591:       return;
1592:     }
1593:     if (state.screen === 'results' || state.screen === 'champion') {
1594:       if (state.game) {
1595:         // subtle slow camera while results are open
1596:         state.game.time += dt * 0.15;
1597:         updateCameraFrozen(state.game, dt);
1598:         state.renderer.render(state.game.scene, state.camera);
1599:       } else {
1600:         animateShowroom(dt, now);
1601:         state.renderer.render(state.menuScene || new THREE.Scene(), state.menuCamera);
1602:       }
1603:       return;
1604:     }
1605:   }
1606: 
1607:   if (state.screen === 'race' && state.game) {
1608:     updateRace(dt);
1609:     state.renderer.render(state.game.scene, state.camera);
1610:   }
1611: }
