10: function normalizeBike(scene, yaw) {
11:   const wrap = new THREE.Group();
12:   const inner = scene;
13:   inner.updateMatrixWorld(true);
14:   const box = new THREE.Box3().setFromObject(inner);
15:   const center = new THREE.Vector3();
16:   const size = new THREE.Vector3();
17:   box.getSize(size);
18:   box.getCenter(center);
19:   inner.position.set(-center.x, -box.min.y, -center.z);
20:   inner.rotation.y = yaw;
21:   inner.traverse(o => {
22:     if (!o.isMesh) return;
23:     o.castShadow = true;
24:     o.receiveShadow = false;
25:     o.frustumCulled = true;
26:     const mats = Array.isArray(o.material) ? o.material : [o.material];
27:     for (const m of mats) {
28:       if (!m) continue;
29:       m.envMapIntensity = 0.85;
30:       if (m.map) m.map.colorSpace = THREE.SRGBColorSpace;
31:       m.roughness = Math.min(0.95, (m.roughness ?? 0.5) * 0.95 + 0.05);
32:     }
33:   });
34:   wrap.add(inner);
35:   wrap.userData.size = size;
36:   return wrap;
37: }
