1104: function updateCollisions(game) {
1105:   const racers = game.racers;
1106:   for (let i = 0; i < racers.length; i++) {
1107:     for (let j = i + 1; j < racers.length; j++) {
1108:       const a = racers[i], b = racers[j];
1109:       const dx = b.pos.x - a.pos.x, dz = b.pos.z - a.pos.z;
1110:       const d2 = dx * dx + dz * dz;
1111:       const min = 1.55;
1112:       if (d2 > min * min || d2 < 0.0001) continue;
1113:       const d = Math.sqrt(d2);
1114:       const nx = dx / d, nz = dz / d;
1115:       const push = (min - d) * 0.5 + 0.01;
1116:       a.pos.x -= nx * push; a.pos.z -= nz * push;
1117:       b.pos.x += nx * push; b.pos.z += nz * push;
1118:       const rel = (b.vel.x - a.vel.x) * nx + (b.vel.y - a.vel.y) * nz;
1119:       if (a.isPlayer || b.isPlayer) {
1120:         game.shake = Math.min(0.8, 0.25 + Math.abs(rel) * 0.02);
1121:         if (Math.abs(rel) > 4) state.audio.blip(120, 0.12, 'sawtooth', 0.1);
1122:       }
1123:       if (rel < 0) {
1124:         if (a.isPlayer) { a.vel.multiplyScalar(0.97); }
1125:         if (b.isPlayer) { b.vel.multiplyScalar(0.97); }
1126:       }
1127:     }
1128:   }
1129: }
