1186: function updateCamera(game, dt) {
1187:   const p = game.player;
1188:   const fwd = new THREE.Vector3(-Math.sin(p.yaw), 0, -Math.cos(p.yaw));
1189:   const right = new THREE.Vector3(Math.cos(p.yaw), 0, -Math.sin(p.yaw));
1190:   const speedNorm = clamp(p.speed / 63, 0, 1.25);
1191: 
1192:   const chaseDist = 5.0 + speedNorm * 0.8;
1193:   const chaseHeight = 1.85 + speedNorm * 0.18;
1194:   const desired = p.pos.clone()
1195:     .addScaledVector(fwd, -chaseDist)
1196:     .addScaledVector(right, -p.lean * 0.7)
1197:     .add(new THREE.Vector3(0, chaseHeight, 0));
1198: 
1199:   const look = p.pos.clone()
1200:     .addScaledVector(fwd, 6.6 + speedNorm * 7)
1201:     .add(new THREE.Vector3(0, 1.0, 0));
1202: 
1203:   let posTarget = desired;
1204:   let lookTarget = look;
1205: 
1206:   if (game.phase === 'countdown') {
1207:     game.intro = clamp(game.intro + dt / 3.4, 0, 1);
1208:     const t = game.intro;
1209:     const e = t * t * (3 - 2 * t);
1210:     const introPos = p.pos.clone().addScaledVector(fwd, -6.0).addScaledVector(right, -2.7).add(new THREE.Vector3(0, 2.35, 0));
1211:     const introLook = p.pos.clone().addScaledVector(fwd, 24).add(new THREE.Vector3(0, 2.2, 0));
1212:     posTarget = introPos.lerp(desired, e);
1213:     lookTarget = introLook.lerp(look, e);
1214:   } else if (game.phase === 'finishing' || game.phase === 'done') {
1215:     const t = game.time * 0.4;
1216:     posTarget = p.pos.clone().add(new THREE.Vector3(Math.cos(t) * 6.5, 2.6, Math.sin(t) * 6.5));
1217:     lookTarget = p.pos.clone().add(new THREE.Vector3(0, 0.9, 0));
1218:   }
1219: 
1220:   const lambda = game.phase === 'countdown' ? 3.2 : 22;
1221:   game.cameraPos.x = damp(game.cameraPos.x, posTarget.x, lambda, dt);
1222:   game.cameraPos.y = damp(game.cameraPos.y, posTarget.y, lambda, dt);
1223:   game.cameraPos.z = damp(game.cameraPos.z, posTarget.z, lambda, dt);
1224:   game.cameraLook.x = damp(game.cameraLook.x, lookTarget.x, 16, dt);
1225:   game.cameraLook.y = damp(game.cameraLook.y, lookTarget.y, 16, dt);
1226:   game.cameraLook.z = damp(game.cameraLook.z, lookTarget.z, 16, dt);
1227: 
1228:   // shake
1229:   game.shake = Math.max(0, game.shake - dt * 2.4);
1230:   const shakeAmt = game.shake * 0.16 + (p.boost ? 0.025 : 0) + speedNorm * 0.006;
1231:   const sx = (Math.random() - 0.5) * shakeAmt;
1232:   const sy = (Math.random() - 0.5) * shakeAmt;
1233: 
1234:   state.camera.position.set(game.cameraPos.x + sx, game.cameraPos.y + sy, game.cameraPos.z);
1235:   state.camera.lookAt(game.cameraLook);
1236:   state.camera.rotation.z += p.lean * 0.035;
1237: 
1238:   const targetFov = 58 + speedNorm * 8 + (p.boost ? 5 : 0);
1239:   state.camera.fov = damp(state.camera.fov, targetFov, 4, dt);
1240:   state.camera.updateProjectionMatrix();
1241: 
1242:   // shadow follows player
1243:   const env = game.env;
1244:   env.sun.position.copy(p.pos).addScaledVector(env.sunDir, 150);
1245:   env.sun.target.position.copy(p.pos);
