420: async function startRound(roundIndex, practice = false) {
421:   state.audio.init();
422:   state.audio.resume();
423:   const round = ROUNDS[roundIndex];
424:   if (!round) return;
425:   hideAllScreens();
426:   $('loading').classList.remove('hidden');
427:   $('loadText').textContent = 'ПОДГОТОВКА ТРАССЫ…';
428:   $('loadFill').style.width = '60%';
429: 
430:   // Let the browser paint the loading state once before heavy synchronous work.
431:   await new Promise(r => requestAnimationFrame(() => setTimeout(r, 20)));
432: 
433:   teardownGame();
434:   const theme = THEMES[round.theme];
435:   const scene = new THREE.Scene();
436:   scene.environment = state.envMap;
437:   scene.environmentIntensity = 0.55;
438:   const track = buildTrack(TRACKS[round.trackId], state.renderer);
439:   scene.add(track.group);
440: 
441:   const env = setupEnvironment(scene, theme, state.renderer);
442:   const particles = makeParticleSystems(scene);
443:   state.renderer.toneMappingExposure = theme.exposure;
444: 
445:   const game = {
446:     roundIndex, round, practice, theme, track, env, particles, scene,
447:     racers: [], player: null, phase: 'countdown', countdown: 4.0,
448:     goTimer: 0, raceTime: 0, paused: false, resultsTimer: -1,
449:     msgTimer: 0, lastCount: null, lastPosition: 6, positionFlash: 0,
450:     finishedOrder: null, shake: 0,
451:     cameraPos: new THREE.Vector3(), cameraLook: new THREE.Vector3(),
452:     intro: 0, minimap: null, resultsShown: false, started: false,
453:     wrongWay: false, lastLapCrossings: 0, skid: 0, time: 0,
454:     lightsOn: 0,
455:   };
456:   state.game = game;
457: 
458:   // player starts P4, with two rivals behind and three ahead
459:   const accent = state.save.bike === 1 ? '#32e6ff' : '#ff6417';
460:   const player = makeRacer('player', 'ВЫ', accent, state.save.bike, true, 3, 1);
461:   game.player = player;
462:   game.racers.push(player);
463: 
464:   // bots fill the remaining grid slots
465:   const botSlots = [0, 1, 2, 4, 5];
466:   RIDER_POOL.forEach((rider, i) => {
467:     const skill = rider.baseSkill * (0.86 + round.difficulty * 0.18);
468:     const bot = makeRacer(rider.id, rider.name, rider.accent, rider.bike, false, botSlots[i], skill);
469:     bot.short = rider.short;
470:     game.racers.push(bot);
471:   });
472: 
473:   // place on grid
474:   game.racers.forEach((r) => {
475:     const slot = track.gridSlots[r.gridSlot];
476:     r.pos.copy(slot.p);
477:     r.yaw = slot.yaw;
478:     r.hintIdx = track.nearest(r.pos).idx;
479:     r.lastIdx = r.hintIdx;
480:     r.lineOffset = (r.gridSlot % 2 === 0 ? 1 : -1) * (1.4 + Math.random() * 1.0);
481:     r.progress = track.nearest(r.pos).s - track.length;
482:     r.visual.root.position.copy(r.pos);
483:     r.visual.root.rotation.y = r.yaw;
484:     scene.add(r.visual.root);
485:   });
486: 
487:   // first nearest pass cache
488:   game.racers.forEach((r) => {
489:     const n = track.nearest(r.pos, r.hintIdx);
490:     r.hintIdx = n.idx;
491:     r.lastIdx = n.idx;
492:     r.progress = (r.crossings - 1) * track.length + n.s;
493:   });
494: 
495:   game.minimap = buildMinimap(track, round);
496:   buildHUD(game);
497:   updateHUD(game, 0, true);
498: 
499:   // camera intro origin: behind-left, looking down the road at the start gantry
500:   const p = player.pos;
501:   const f = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
502:   const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
503:   game.cameraPos.copy(p).addScaledVector(f, -6.0).addScaledVector(right, -2.7).add(new THREE.Vector3(0, 2.35, 0));
504:   game.cameraLook.copy(p).addScaledVector(f, 24).add(new THREE.Vector3(0, 2.2, 0));
505:   state.camera.position.copy(game.cameraPos);
506:   state.camera.lookAt(game.cameraLook);
507: 
508:   state.screen = 'race';
509:   $('loading').classList.add('hidden');
510:   $('hud').classList.remove('hidden');
511:   if (state.touch) $('touch').classList.remove('hidden');
512:   document.body.classList.add('in-race');
513: 
514:   game.countdown = 4.0;
515:   game.lastCount = null;
516:   showHUDMessage('');
517:   $('countdown').textContent = '';
518:   $('countdown').className = 'countdown';
519:   setTimeout(() => {
520:     $('banner').textContent = round.name;
521:     $('banner').classList.remove('show');
522:     void $('banner').offsetWidth;
523:     $('banner').classList.add('show');
524:   }, 350);
525:   state.audio.blip(320, 0.12, 'sine', 0.1);
526: }
