690: function updateStartLights(game) {
691:   const lights = game.track.startLights;
692:   const cd = game.countdown;
693:   // 5 lights, one every 0.6s while counting down from 4.0 to 1.0
694:   const lit = game.phase === 'countdown' ? clamp(Math.floor((4.0 - cd) / 0.58) + 1, 0, 5) : 5;
695:   const green = game.phase !== 'countdown';
696:   lights.forEach((l, i) => {
697:     const on = green || i < lit;
698:     const c = green ? 0x2dff7a : 0xff2b18;
699:     l.mat.emissive.setHex(on ? c : 0x220000);
700:     l.mat.emissiveIntensity = on ? 3 : 0.4;
701:     l.mat.color.setHex(on ? c : 0x151515);
702:     l.glow.material.opacity = on ? (green ? 0.85 : 0.6) : 0;
703:     l.glow.material.color.setHex(c);
704:   });
705:   if (green && game.phase === 'racing') {
706:     game.goTimer += 1 / 60;
707:     if (game.goTimer > 1.3) {
708:       lights.forEach((l) => { l.glow.material.opacity = 0; });
709:     }
710:   }
711: }
