722:     keys[k] = true;
723:     if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
724:     if (state.screen === 'race' && state.game && !state.game.paused) {
725:       if (k === 'escape') togglePause();
726:       if (k === 'r') restartRace();
727:       if (k === 'm') toggleSound();
728:     } else if (state.screen === 'pause' || (state.game && state.game.paused)) {
729:       if (k === 'escape') togglePause();
730:     }
