1053: function onLapCross(game, r) {
1054:   const track = game.track;
1055:   if (r.crossings <= 0) return;
1056:   if (r.isPlayer) {
1057:     if (r.crossings === 1) {
1058:       r.lapStart = game.raceTime;
1059:     } else {
1060:       const lap = game.raceTime - r.lapStart;
1061:       r.lapStart = game.raceTime;
1062:       r.lapTimes.push(lap);
1063:       if (lap < r.bestLap) r.bestLap = lap;
1064:       $('lastLap').textContent = `ПОСЛ. ${fmtTime(lap)}`;
1065:       $('bestLap').textContent = `ЛУЧШ. ${fmtTime(r.bestLap)}`;
1066:       state.audio.blip(820, 0.08, 'square', 0.09);
1067:     }
1068:     if (r.crossings >= 2 && r.crossings === game.round.laps) {
1069:       triggerBanner('ПОСЛЕДНИЙ КРУГ');
1070:       state.audio.blip(500, 0.18, 'sawtooth', 0.12);
1071:     } else if (r.crossings >= 2 && r.crossings < game.round.laps) {
1072:       triggerBanner(`КРУГ ${r.crossings}`);
1073:       state.audio.blip(620, 0.12, 'square', 0.1);
1074:     }
1075:     if (r.crossings === game.round.laps + 1) {
1076:       r.finished = true;
1077:       r.finishTime = game.raceTime;
1078:       r.boost = false;
1079:       game.player.boost = false;
1080:       triggerBanner('ФИНИШ');
1081:       state.audio.blip(1000, 0.4, 'sawtooth', 0.15);
1082:       game.resultsTimer = 2.2;
1083:     }
1084:   } else {
1085:     if (r.crossings === 1) r.lapStart = game.raceTime;
1086:     if (r.crossings === game.round.laps + 1 && !r.finished) {
1087:       r.finished = true;
1088:       r.finishTime = game.raceTime;
1089:     }
1090:   }
1091: }
