1168:       game.particles.sparks.spawn(rear, new THREE.Vector3((Math.random() - 0.5) * 2, Math.random() * 2, (Math.random() - 0.5) * 2), { color: 0xffa030, size: 0.5, life: 0.18 });
1169:     }
