232:     this.cursor = (this.cursor + 1) % this.count;
233:     this.positions[i * 3] = pos.x;
234:     this.positions[i * 3 + 1] = pos.y;
235:     this.positions[i * 3 + 2] = pos.z;
236:     this.vel[i * 3] = vel.x;
237:     this.vel[i * 3 + 1] = vel.y;
