   if(g.phase==='countdown'){APEX.updateRace(dt);continue;}
   const n=g.track.nearest(p.pos,p.hintIdx), ahead=g.track.pointAt(n.s+Math.max(14,p.speed*.62));
   let target=ahead.p.clone().addScaledVector(ahead.r,-n.lateral*.55);
   const dx=target.x-p.pos.x,dz=target.z-p.pos.z;
   const desired=Math.atan2(-dx,-dz); const err=Math.atan2(Math.sin(desired-p.yaw),Math.cos(desired-p.yaw));
   const steer=err>.035?'a':err<-.035?'d':'';
   if(steer!==held){if(held)key('keyup',held);if(steer)key('keydown',steer);held=steer;}
   key('keydown','w'); APEX.updateRace(dt);
   if(i%600===599)trace.push({t:+((i+1)*dt).toFixed(1),lap:p.crossings,laps:p.lapTimes.map(x=>+x.toFixed(1)),v:+p.speed.toFixed(1),off:p.offroad,lat:+p.lateral.toFixed(1),pos:p.pos.toArray().map(x=>+x.toFixed(1)),err:+err.toFixed(2)});
   if(g.phase==='done')break;
  }
  if(held)key('keyup',held);key('keyup','w');const g=APEX.game,p=g.player;return {phase:g.phase,raceTime:g.raceTime,cross:p.crossings,laps:p.lapTimes,finished:p.finished,trace};
 }); console.log(JSON.stringify(res,null,2)); await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

