const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:800}}),errors=[];
 page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
 await page.goto('http://localhost:3000/');await page.waitForFunction(()=>window.APEX);
 const checks=[];
 await page.evaluate(()=>APEX.startRound(0,true));await page.waitForFunction(()=>APEX.game);await page.waitForTimeout(300);
 checks.push({stage:'race',screen:await page.evaluate(()=>APEX.state.screen)});
 await page.keyboard.press('Escape');checks.push({stage:'pause',screen:await page.evaluate(()=>APEX.state.screen),visible:await page.locator('#pause').isVisible()});
 await page.locator('#resumeBtn').click();checks.push({stage:'resume',screen:await page.evaluate(()=>APEX.state.screen)});
 const prior=await page.evaluate(()=>APEX.game);await page.keyboard.press('r');await page.waitForFunction(old=>APEX.game!==old,prior);await page.waitForTimeout(300);checks.push({stage:'restart',screen:await page.evaluate(()=>APEX.state.screen),round:await page.evaluate(()=>APEX.game.roundIndex)});
 await page.keyboard.press('Escape');await page.locator('#quitBtn').click();await page.waitForFunction(()=>APEX.state.screen==='menu');checks.push({stage:'menu',screen:await page.evaluate(()=>APEX.state.screen),visible:await page.locator('#menu').isVisible()});
 console.log(JSON.stringify({checks,errors},null,2));await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

